// Shared ImGui project dialogs; service owns paths, saves and lifecycle. Signed: President.
#include "project.h"
#include "hub.h"
#include "../labs/lab.h"
#include "../editor_shell/shell.h"
#include "imgui.h"
#include <string>
namespace {int action=0,save_wait=0;bool show=false;char path[8192]="",name[256]="New project";unsigned long long generation=0;std::string message;}
extern "C" void ps_project_ui_reset(){action=save_wait=0;show=false;}
extern "C" bool ps_project_ui_open(){return action!=0;}
extern "C" void ps_project_prompt(int value){PsProjectInfo info{};ps_project_info(&info);action=value;generation=info.generation;show=true;save_wait=0;message.clear();}
extern "C" void ps_project_ui(){if(!action)return;
 if(save_wait>0&&--save_wait==0){BslShellState state{};bsl_shell_snapshot(&state);if(state.terrain_dirty||state.placements_dirty||ps_hub_has_drafts())message="Some edits could not be saved. Resolve the reported error; committed files remain saved.";else {PsProjectRequest r{1,PS_PROJECT_SAVE,generation,nullptr,nullptr};PsProjectReply reply{};if(ps_project_request(&r,&reply)==PS_TEST_ACCEPTED){message="Project sources and settings saved.";}else message=reply.message;}}if(show){ImGui::OpenPopup("Project workspace");show=false;}ImGui::SetNextWindowSize(ImVec2(640,0),ImGuiCond_Appearing);if(ImGui::BeginPopupModal("Project workspace",nullptr,ImGuiWindowFlags_AlwaysAutoResize)){
 const char* label=action==PS_PROJECT_NEW?"New project":action==PS_PROJECT_OPEN?"Open project":action==PS_PROJECT_COPY?"Save project copy":"Save project";ImGui::SeparatorText(label);if(action!=PS_PROJECT_SAVE){ImGui::TextWrapped(action==PS_PROJECT_OPEN?"Select a project directory or its powersurge.project.json file. Opening replaces the current level.":"Enter a NEW project folder under an existing parent. Existing folders are never overwritten. The new project opens after copying; normal progress is not imported.");ImGui::SetNextItemWidth(-1);ImGui::InputText("##folder",path,sizeof path);if(action!=PS_PROJECT_OPEN){ImGui::TextUnformatted("Project name");ImGui::SetNextItemWidth(-1);ImGui::InputText("##name",name,sizeof name);}}else ImGui::TextWrapped("Save database drafts, level edits and the current entry level. Files commit individually; a later failure preserves earlier successful saves.");
 ImGui::TextWrapped("Unsaved changes block project replacement. Laboratory tests and their progress stay separate from project files.");ImGui::BeginDisabled(save_wait>0);if(ImGui::Button(label)){if(action==PS_PROJECT_SAVE){PsProjectInfo info{};ps_project_info(&info);PsLabTestInfo test{};ps_lab_test_info(&test);if(!info.persistent||test.active||test.pending)message="Open a permanent source project and stop its test first. Use Save project copy for a laboratory.";else if(ps_hub_save_all()){bsl_shell_submit("save",0);save_wait=3;message="Saving project sources...";}else message="Database save failed; resolve the database diagnostics before continuing.";}else {PsProjectRequest request{1,action,generation,path,name};PsProjectReply reply{};if(ps_project_request(&request,&reply)==PS_TEST_ACCEPTED){action=0;ImGui::CloseCurrentPopup();}message=reply.message;}}ImGui::EndDisabled();ImGui::SameLine();if(ImGui::Button("Cancel")){action=0;ImGui::CloseCurrentPopup();}if(!message.empty())ImGui::TextWrapped("%s",message.c_str());ImGui::EndPopup();}}
